package main

import (
	"embed"
	"encoding/json"
	"fmt"
	"sort"
	"strings"
)

//go:embed all:data/hsk.json
var hskData embed.FS

// hskDataPath is the embedded vocabulary, generated by `make hsk` and
// committed (see data/PROVENANCE.md for the shape and its source).
const hskDataPath = "data/hsk.json"

// gapTarget is the share of a level the user should have met before the app
// treats the next one as their level. Below it, that level's unseen words are
// the gap list.
const gapTarget = 0.8

// gapPage is how many gap rows a response carries by default; the client asks
// for more instead of receiving a five-hundred-row wall.
const gapPage = 50

// knownPage is how many known-word rows a response carries by default. Same
// bargain as gapPage: a page, not everything the user has ever met.
const knownPage = 50

// maxRefs caps how many library items one word points back at. A word like 的
// turns up in nearly every item; the row carries a few references and the count
// behind them, and the rest is a library search away.
const maxRefs = 3

// defaultKnownLevels is what the known-word list covers until the client asks
// for other bands. The first three levels are where a learner actually lives;
// dumping all seven turns the list into a wall nobody reads.
var defaultKnownLevels = []int{1, 2, 3}

// hskWord is one vocabulary row in the embedded file.
type hskWord struct {
	Simplified string `json:"s"`
	Level      int    `json:"lv"`
	Frequency  int    `json:"q"`
	Pinyin     string `json:"py"`
	Gloss      string `json:"m"`

	// sortKey is Pinyin with its tone marks folded away, computed once at
	// startup. It exists only to put lists in alphabetical order: "wǒ" has to
	// sort under "wo", not after every plain ASCII word as its code points
	// would. Unexported, so it never travels to the client.
	sortKey string
}

// hskIndex is the vocabulary, parsed once at startup: a map by simplified form
// for matching, and per-level slices already in alphabetical order so a list
// needs no sorting.
type hskIndex struct {
	byWord   map[string]hskWord
	byLevel  map[int][]hskWord
	levels   []int
	maxRunes int
}

// loadHSK parses the embedded vocabulary.
func loadHSK() (*hskIndex, error) {
	raw, err := hskData.ReadFile(hskDataPath)
	if err != nil {
		return nil, fmt.Errorf("read embedded vocabulary: %w", err)
	}
	return parseHSK(raw)
}

// parseHSK builds the index from raw JSON.
func parseHSK(raw []byte) (*hskIndex, error) {
	var words []hskWord
	if err := json.Unmarshal(raw, &words); err != nil {
		return nil, fmt.Errorf("decode vocabulary: %w", err)
	}
	if len(words) == 0 {
		return nil, fmt.Errorf("vocabulary is empty")
	}

	index := &hskIndex{
		byWord:  make(map[string]hskWord, len(words)),
		byLevel: make(map[int][]hskWord),
	}

	for _, word := range words {
		if word.Simplified == "" || word.Level <= 0 {
			return nil, fmt.Errorf("malformed vocabulary row: %+v", word)
		}
		word.sortKey = foldTones(word.Pinyin)
		index.byWord[word.Simplified] = word
		index.byLevel[word.Level] = append(index.byLevel[word.Level], word)
		index.maxRunes = max(index.maxRunes, len([]rune(word.Simplified)))
	}

	for level, levelWords := range index.byLevel {
		sort.SliceStable(levelWords, func(i, j int) bool {
			// Alphabetical by pinyin, so a band reads like a dictionary page
			// and words are where you expect to find them. Ties between
			// homophones fall back to the tone-marked spelling, then to the
			// characters, to keep the order stable.
			if levelWords[i].sortKey != levelWords[j].sortKey {
				return levelWords[i].sortKey < levelWords[j].sortKey
			}
			if levelWords[i].Pinyin != levelWords[j].Pinyin {
				return levelWords[i].Pinyin < levelWords[j].Pinyin
			}
			return levelWords[i].Simplified < levelWords[j].Simplified
		})
		index.byLevel[level] = levelWords
		index.levels = append(index.levels, level)
	}
	sort.Ints(index.levels)

	return index, nil
}

// toneFolds maps the tone-marked vowels pinyin uses onto plain letters. Pinyin
// has a small, closed set of them, so an explicit table beats pulling in a
// Unicode normaliser for this.
var toneFolds = map[rune]string{
	'ā': "a", 'á': "a", 'ǎ': "a", 'à': "a",
	'ē': "e", 'é': "e", 'ě': "e", 'è': "e", 'ê': "e",
	'ī': "i", 'í': "i", 'ǐ': "i", 'ì': "i",
	'ō': "o", 'ó': "o", 'ǒ': "o", 'ò': "o",
	'ū': "u", 'ú': "u", 'ǔ': "u", 'ù': "u",
	'ǖ': "u", 'ǘ': "u", 'ǚ': "u", 'ǜ': "u", 'ü': "u",
	'ń': "n", 'ň': "n", 'ǹ': "n",
	'ḿ': "m",
}

// foldTones is the sort key for one pinyin string: lower case, tone marks
// removed, ü written as u. Nothing else changes, so "yín háng" becomes
// "yin hang" and keeps its syllable break.
func foldTones(pinyin string) string {
	var out strings.Builder
	out.Grow(len(pinyin))
	for _, r := range strings.ToLower(pinyin) {
		if plain, ok := toneFolds[r]; ok {
			out.WriteString(plain)
			continue
		}
		out.WriteRune(r)
	}
	return out.String()
}

// levelCoverage is one bar in the HSK tab.
type levelCoverage struct {
	Level int `json:"level"`
	Seen  int `json:"seen"`
	Total int `json:"total"`
}

// wordRef points back at one library item a vocabulary word came from. The
// text is the item's Chinese, so a row can say "you met this in 我去银行取钱"
// without the client having to join anything.
type wordRef struct {
	ID   string `json:"id"`
	Text string `json:"text"`
}

// wordRefs is one word's references: the few that travel with the row and the
// total behind them. Identical texts count once — saving the same sentence
// twice should not produce two identical chips.
type wordRefs struct {
	Items []wordRef
	Total int
	seen  map[string]struct{}
}

// knownWord is a vocabulary row plus the library items it was found in.
type knownWord struct {
	hskWord
	Refs     []wordRef `json:"refs,omitempty"`
	RefTotal int       `json:"ref_total,omitempty"`
}

// wordPage is one page of rows plus enough metadata to offer "load more".
type wordPage struct {
	Words []knownWord `json:"words"`
	Total int         `json:"total"`
	More  bool        `json:"more"`
}

// coverageReport is the whole HSK tab payload: the per-level bars, the map's
// current level, the words the user has actually met, and what that level is
// still missing.
type coverageReport struct {
	Levels  []levelCoverage `json:"levels"`
	Current int             `json:"current"`
	Known   wordPage        `json:"known"`
	Gaps    wordPage        `json:"gaps"`
}

// coverageQuery is what the tab asked for. Zero values mean "the app's
// default": the first three bands, the map's current level, one page each.
type coverageQuery struct {
	KnownLevels []int // bands the known-word list covers
	KnownPage   int   // how many known rows to return
	GapLevel    int   // band to list gaps for; 0 means the current level
	GapPage     int   // how many gap rows to return
}

// coverage maps the user's saved Chinese onto the HSK levels: how much of each
// level they have met, which level to work from, the words they met (with the
// items that taught them), and what the chosen level is still missing.
func (h *hskIndex) coverage(items []Item, query coverageQuery) coverageReport {
	seen, refs := h.harvest(items)

	report := coverageReport{Levels: make([]levelCoverage, 0, len(h.levels))}
	for _, level := range h.levels {
		words := h.byLevel[level]
		hit := 0
		for _, word := range words {
			if _, ok := seen[word.Simplified]; ok {
				hit++
			}
		}
		report.Levels = append(report.Levels, levelCoverage{Level: level, Seen: hit, Total: len(words)})
	}
	if len(report.Levels) == 0 {
		return report
	}

	// The current level is the lowest one still below the target; once every
	// level clears it, the highest level is the map's edge.
	report.Current = report.Levels[len(report.Levels)-1].Level
	for _, row := range report.Levels {
		if float64(row.Seen)/float64(row.Total) < gapTarget {
			report.Current = row.Level
			break
		}
	}

	knownLevels := query.KnownLevels
	if len(knownLevels) == 0 {
		knownLevels = defaultKnownLevels
	}
	report.Known = h.knownPage(seen, refs, knownLevels, query.KnownPage)

	gapLevel := query.GapLevel
	if gapLevel == 0 {
		gapLevel = report.Current
	}
	report.Gaps = h.gapPage(seen, gapLevel, query.GapPage)

	return report
}

// knownPage collects the words the user has met inside the given bands, each
// with the items it came from, in pinyin order within each band.
func (h *hskIndex) knownPage(seen map[string]struct{}, refs map[string]*wordRefs, levels []int, page int) wordPage {
	if page <= 0 {
		page = knownPage
	}
	out := wordPage{Words: make([]knownWord, 0, min(page, knownPage))}

	for _, level := range levels {
		for _, word := range h.byLevel[level] {
			if _, ok := seen[word.Simplified]; !ok {
				continue
			}
			out.Total++
			if len(out.Words) < page {
				row := knownWord{hskWord: word}
				if found := refs[word.Simplified]; found != nil {
					row.Refs, row.RefTotal = found.Items, found.Total
				}
				out.Words = append(out.Words, row)
			}
		}
	}
	out.More = out.Total > len(out.Words)

	return out
}

// gapPage collects one band's unseen words, in pinyin order.
func (h *hskIndex) gapPage(seen map[string]struct{}, level, page int) wordPage {
	if page <= 0 {
		page = gapPage
	}
	out := wordPage{Words: make([]knownWord, 0, min(page, gapPage))}

	for _, word := range h.byLevel[level] {
		if _, ok := seen[word.Simplified]; ok {
			continue
		}
		out.Total++
		if len(out.Words) < page {
			out.Words = append(out.Words, knownWord{hskWord: word})
		}
	}
	out.More = out.Total > len(out.Words)

	return out
}

// hasLevel reports whether the vocabulary knows this band.
func (h *hskIndex) hasLevel(level int) bool {
	_, ok := h.byLevel[level]
	return ok
}

// seenWords returns every vocabulary word that appears in the saved text.
//
// Matching is forward maximum matching against the vocabulary itself: at each
// position take the longest word that fits, then jump past it. That is what
// makes 银行 inside a saved sentence count as 银行 rather than as 银 + 行, and
// it keeps a single character like 的 from being counted out of the middle of
// an unrelated word. It needs no segmenter and no extra data — the dictionary
// is the segmenter.
func (h *hskIndex) seenWords(texts []string) map[string]struct{} {
	items := make([]Item, len(texts))
	for i, text := range texts {
		items[i] = Item{Chinese: text}
	}
	seen, _ := h.harvest(items)
	return seen
}

// harvest matches every saved item against the vocabulary once, returning both
// the set of met words and, per word, the items it was found in.
func (h *hskIndex) harvest(items []Item) (map[string]struct{}, map[string]*wordRefs) {
	seen := make(map[string]struct{}, len(items)*4)
	refs := make(map[string]*wordRefs)

	for _, item := range items {
		// One item is one sighting: a word saved twice in the same sentence
		// should point back at that sentence once.
		counted := make(map[string]struct{})
		h.matchInto(item.Chinese, func(word string) {
			if _, done := counted[word]; done {
				return
			}
			counted[word] = struct{}{}
			seen[word] = struct{}{}

			found := refs[word]
			if found == nil {
				found = &wordRefs{seen: make(map[string]struct{})}
				refs[word] = found
			}
			if _, dup := found.seen[item.Chinese]; dup {
				return
			}
			found.seen[item.Chinese] = struct{}{}

			found.Total++
			if len(found.Items) < maxRefs {
				found.Items = append(found.Items, wordRef{ID: item.ID, Text: item.Chinese})
			}
		})
	}

	return seen, refs
}

// matchInto walks one text and reports each vocabulary word it contains, in
// order of appearance.
func (h *hskIndex) matchInto(text string, visit func(string)) {
	runes := []rune(text)
	for i := 0; i < len(runes); {
		matched := 0
		for length := min(h.maxRunes, len(runes)-i); length >= 1; length-- {
			if _, ok := h.byWord[string(runes[i:i+length])]; ok {
				matched = length
				break
			}
		}
		if matched == 0 {
			i++ // not the start of any known word: skip one character
			continue
		}
		visit(string(runes[i : i+matched]))
		i += matched
	}
}
